from atlassian import Confluence
from bs4 import BeautifulSoup
from markdownify import markdownify
from dataclasses import dataclass

from knowledge_service.config import settings


@dataclass
class Document:
    id: str
    title: str
    content: str
    url: str
    space: str
    metadata: dict


class ConfluenceScraper:
    def __init__(self):
        self.client = Confluence(
            url=settings.confluence_url,
            username=settings.confluence_username,
            password=settings.confluence_api_token,
        )

    def get_spaces(self) -> list[dict]:
        """Get all accessible spaces."""
        return self.client.get_all_spaces(start=0, limit=500)["results"]

    def get_pages_in_space(self, space_key: str, limit: int = 100) -> list[dict]:
        """Get all pages in a space."""
        return self.client.get_all_pages_from_space(
            space_key, start=0, limit=limit, expand="body.storage"
        )

    def html_to_markdown(self, html: str) -> str:
        """Convert Confluence HTML to clean markdown."""
        soup = BeautifulSoup(html, "html.parser")

        # Remove unwanted elements
        for tag in soup.find_all(["script", "style", "meta"]):
            tag.decompose()

        return markdownify(str(soup), heading_style="ATX", code_language="python")

    def scrape_page(self, page_id: str) -> Document:
        """Scrape a single page by ID."""
        page = self.client.get_page_by_id(
            page_id, expand="body.storage,space,version"
        )

        html_content = page["body"]["storage"]["value"]
        markdown_content = self.html_to_markdown(html_content)

        return Document(
            id=page["id"],
            title=page["title"],
            content=markdown_content,
            url=f"{settings.confluence_url}/wiki/spaces/{page['space']['key']}/pages/{page['id']}",
            space=page["space"]["key"],
            metadata={
                "version": page["version"]["number"],
                "last_modified": page["version"]["when"],
                "author": page["version"]["by"]["displayName"],
            },
        )

    def scrape_space(self, space_key: str, limit: int = 100) -> list[Document]:
        """Scrape all pages in a space."""
        pages = self.get_pages_in_space(space_key, limit)
        documents = []

        for page in pages:
            try:
                doc = self.scrape_page(page["id"])
                documents.append(doc)
            except Exception as e:
                print(f"Error scraping page {page['id']}: {e}")

        return documents

