            if start > 5000:
                break

        return matching_spaces

    def get_space(self, space_key: str) -> dict | None:
        """Get a specific space by key."""
        try:
            return self.client.get_space(space_key)
        except Exception:
            return None

    def get_pages_in_space(self, space_key: str, max_pages: int | None = None) -> list[dict]:
        """Get all pages in a space with pagination.

        Args:
            space_key: The Confluence space key
            max_pages: Maximum number of pages to fetch. None = fetch all.
        """
        all_pages = []
        start = 0
        batch_size = 100  # Confluence API max per request

        while True:
            pages = self.client.get_all_pages_from_space(
                space_key, start=start, limit=batch_size, expand="body.storage"
            )

            if not pages:
                break

            all_pages.extend(pages)
            print(f"  Fetched {len(all_pages)} pages...")

            # Check if we've reached the max
            if max_pages and len(all_pages) >= max_pages:
                all_pages = all_pages[:max_pages]
                break

            # Check if there are more pages
            if len(pages) < batch_size:
                break

            start += batch_size

        return all_pages

    def html_to_markdown(self, html: str) -> str:
        """Convert Confluence HTML to clean markdown."""
        soup = BeautifulSoup(html, "html.parser")

        # Remove unwanted elements
        for tag in soup.find_all(["script", "style", "meta"]):
            tag.decompose()

        return markdownify(str(soup), heading_style="ATX", code_language="python")

    def scrape_page(self, page_id: str) -> Document:
        """Scrape a single page by ID."""
        page = self.client.get_page_by_id(
            page_id, expand="body.storage,space,version"
        )

        html_content = page["body"]["storage"]["value"]
        markdown_content = self.html_to_markdown(html_content)

        return Document(
            id=page["id"],
            title=page["title"],
            content=markdown_content,
            url=f"{settings.confluence_url}/wiki/spaces/{page['space']['key']}/pages/{page['id']}",
            space=page["space"]["key"],
            metadata={
                "version": page["version"]["number"],
                "last_modified": page["version"]["when"],
                "author": page["version"]["by"]["displayName"],
            },
        )

    def scrape_space(self, space_key: str, max_pages: int | None = None) -> list[Document]:
        """Scrape all pages in a space."""
        pages = self.get_pages_in_space(space_key, max_pages)
        documents = []

        for page in pages:
            try:
                doc = self.scrape_page(page["id"])
                documents.append(doc)
            except Exception as e:
                print(f"Error scraping page {page['id']}: {e}")

        return documents

